\documentclass[11pt,a4paper]{article}
\usepackage[review]{acl}
% \usepackage{acl}  % uncomment for camera-ready (remove [review])
\usepackage{times,latexsym}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\graphicspath{{../../figures/paper/}}
\usepackage{booktabs}
\usepackage{multirow}
\usepackage{xcolor}
\usepackage{algorithm}
\usepackage{algorithmic}

\title{Trace Verbosity Degrades SFT Verdict Prediction:\\ A Case Study in Information Density Effects}
\author{Anonymous ACL submission}

\begin{document}
\maketitle

\begin{abstract}
In SFT-based binary verdict prediction for code, complete execution traces degrade accuracy by 18--23 percentage points compared to compact exception events, despite containing strictly more information.
Across four code-specialized models (1.5B--13B, three architecture families), verbose traces plateau near the source-code-only baseline (77--82\%) while exception-only input reaches ${\geq}$99.33\%.
Since exception events structurally encode verdict direction, this ceiling is expected; the non-trivial finding is the degradation mechanism: controlled gradient masking places an upper bound of ${\leq}$4\% on backward-pass gradient dilution under matched input format, assigning the remainder to inference-time signal sparsity (diagnostic tokens constitute ${\sim}$1/500 of full traces).
Format-marker removal and cross-dataset transfer confirm the learned signal reflects diagnostic patterns rather than surface shortcuts.
Under compact input, a 7B SFT model surpasses GPT-4o by 12 points (zero-shot, not directly comparable to SFT), a ranking that reverses without trace information, though this comparison is limited to the ${\leq}$13B code-specialized regime tested.
These results decompose trace verbosity into a two-tier signal hierarchy and quantify why more information hurts for this structurally constrained task.
\end{abstract}

\input{introduction}
\input{related_work}
\input{method}
\input{experiments}
\input{discussion}
\input{conclusion}

\section*{Limitations}

\paragraph{Scope.}
All experiments use Python-only benchmarks (HumanEval, MBPP-sanitized; 591 problems with simple assert-based tests); generalization to other languages, non-assert test frameworks, and multi-file projects is unverified.
Python's structured exception hierarchy makes exception events particularly informative; languages with less structured error reporting (e.g., C/C++ segmentation faults) may exhibit different signal distributions.
All four models (1.5B--13B) are code-specialized; 30B+ models or general-purpose LLMs may behave differently, and whether larger models can overcome signal dilution in verbose traces is untested.
Training solutions were sampled from Qwen-2.5-Coder-7B-Instruct; whether the signal hierarchy generalizes to human-written code with different exception distributions is untested.

\paragraph{Variance and robustness.}
Core results are validated with 3 seeds; supplementary comparisons use single-seed runs with Wilson CI estimates for variance.
VOTA's longer sequences are vulnerable to tokenizer-driven truncation: 1 of 12 model-seed combinations suffered catastrophic failure (DeepSeek seed 42: 84.45\%), indicating that VOTA robustness depends on tokenizer efficiency.

\paragraph{Mechanistic analysis.}
The gradient masking experiment isolates backward-pass dilution but does not quantify forward-pass attention effects, leaving a residual confound between gradient and inference-time factors.
CodeLlama \texttt{full\_trace} uses a head-2048 proxy, which may systematically underestimate full-trace performance given that tail-truncation experiments confirm diagnostic information concentrates at the trace terminus.
The VOTA loop compression threshold and assertion-point extraction heuristics were not subjected to sensitivity analysis; different thresholds may shift the Tier~1/Tier~2 boundary.

\bibliography{references}

\appendix
\input{appendix}

\end{document}

The 18.07pp gap between \texttt{exception\_only} (99.83\%) and \texttt{full\_trace} (81.76\%) could reflect gradient dilution (diagnostic tokens are ${\sim}$1/500 of full traces, diluting gradient signal during training) or content quality (verbose input buries diagnostic signals at inference).

\paragraph{Controlled gradient masking.}
To isolate gradient dilution, we mask 99.8\% of gradient updates during \texttt{exception\_only} training, matching the diagnostic token ratio of full traces while preserving compact input.
This yields 99.22\% (mean $-$0.61pp from \texttt{exception\_only}, 3 seeds), limiting gradient dilution to ${\leq}$4\% of the 18.07pp gap under matched train-inference format (Table~\ref{tab:density}).
The gradient masking bound places an upper bound of ${\leq}$4\% on gradient dilution, leaving ${\geq}$96\% to content quality within format (diagnostic signal density at inference), though forward-pass attention during masked training is an unquantified residual; cross-format mismatch effects are not captured by this decomposition (\S\ref{sec:discussion}).
Note that masking affects only the backward pass; the model still attends to all input tokens during the forward pass, so this bounds gradient dilution's contribution but does not rule out attention-based information flow as a residual confound.

\begin{table}[t]
\centering
\caption{Decomposition of the full-trace degradation under matched train-inference format (Qwen-7B). Gradient masking places an upper bound of ${\leq}$4\% on gradient dilution within format; cross-format mismatch effects are not captured (\S\ref{sec:discussion}). Label-only loss provides a confounded but directionally consistent complementary estimate.}
\label{tab:density}
\small
\begin{tabular}{lcc}
\toprule
\textbf{Condition} & \textbf{Acc (\%)} & \textbf{$\Delta$} \\
\midrule
exception\_only & 99.83{\scriptsize$\pm$0.00} & --- \\
\quad + grad mask (99.8\%) & 99.22{\scriptsize$\pm$0.20}$^\S$ & $-$0.61pp \\
full\_trace & 81.76$^\ddag$ & $-$18.07pp \\
\midrule
\multicolumn{3}{l}{\textit{Complementary (confounded):}} \\
full\_trace + label-only loss & 85.94{\scriptsize$\pm$1.12} & +4.50pp$^\dag$ \\
\bottomrule
\end{tabular}
\vspace{2pt}
\par\raggedright\footnotesize
$^\S$Mean $\pm$ std over 3 seeds (42, 123, 456).
$^\ddag$Matched-seed baseline; 3-seed mean 81.44\%$\pm$1.11 (Table~\ref{tab:cross_model}).
$^\dag$vs.\ \texttt{full\_trace} (81.44\%$\pm$1.11); not significant under clustered bootstrap (95\% CI [$-$0.6, +9.8]pp, $n_\text{eff}{=}119$).
\end{table}

\paragraph{Complementary evidence.}
Label-only loss on full traces (+4.50pp, 3 seeds) yields a confounded upper bound of ${\leq}$26\% gradient contribution, consistent with the masking estimate (${\leq}$4\%) but not significant under clustered bootstrap (95\% CI [$-$0.6, +9.8]pp).
Qwen-1.5B shows a similar label-only pattern (17\%/83\%, 3 seeds); CodeLlama and DeepSeek collapse to majority baseline (28.5\%), rendering this Qwen-specific auxiliary evidence, possibly reflecting tokenizer efficiency or attention mechanism differences.
The gradient masking ablation provides a more robust decomposition: DeepSeek-Coder-6.7B (99.33\%) and CodeLlama-13B (100\%) under 99.8\% masking (single seed each) support content quality as the dominant factor across architectures.
All 217 \texttt{full\_trace} errors occur where context-window truncation (the model's 2{,}048-token training limit) removes diagnostic markers: mechanical truncation, not semantic confusion.

\subsection{Complementary Analyses}
\label{sec:additional}

\paragraph{Trace length ablation.}
\label{sec:trace_length}
Varying the head-truncated trace token budget (256--no limit) on Qwen-7B yields accuracy in a narrow 77.2\%--81.8\% band with a non-monotonic pattern: 1024-token prefixes (77.23\%) underperform 512-token prefixes (80.42\%, $p{=}.002$), because mid-length prefixes retain enough irrelevant content to mislead the model while discarding diagnostic events near the trace terminus (Appendix~\ref{sec:trace_length_full}).
Critically, removing the token budget entirely (no truncation) yields 81.76\%, identical to head-2048, ruling out pre-processing truncation (the external token-budget cap applied during data preparation) as the explanation for the full-trace degradation.
This non-monotonicity is specific to head-truncation; under tail-truncation, accuracy increases monotonically for two of three models (Table~\ref{tab:tail_cross_model} in Appendix), with only DeepSeek showing a mild architecture-specific reversal at tail-1024$\to$tail-2048 ($-$1.5pp).

\paragraph{Truncation direction and budget curve.}
Tail-truncation dramatically outperforms head-truncation: tail-2048 exceeds head-2048 by 15.5--22.6pp across three models (Appendix~\ref{sec:trace_length_full}).

\section{Experiments}

We evaluate across two research questions:
(1)~Why do complete traces degrade SFT verdict accuracy despite containing all diagnostic information?
(2)~Which trace components carry the verdict signal, and how does their density affect learning?
All experiments use $N{=}1{,}190$ test samples; accuracy is reported with Wilson 95\% confidence intervals (CIs).\footnote{Problem-level partition (472 train / 119 test, zero crossover; \S\ref{sec:dataset}). \texttt{exception\_only} duplicates (48.99\% test; Appendix~\ref{sec:dedup_stats}) arise from within-problem variants; deduplication yields negligible ($<$0.1pp) delta.}
Pairwise comparisons use paired bootstrap resampling ($B{=}10{,}000$, seed=42); all differences are significant at $p{<}.0001$ unless noted.
Under problem-level clustered bootstrap ($n_\text{eff}{=}119$), all cross-tier gaps remain significant ($p{<}.001$); 3 of 80 within-tier pairwise comparisons lose significance after Holm--Bonferroni correction.

\subsection{Cross-Model Comparison}
\label{sec:cross_model}

Table~\ref{tab:cross_model} compares four models spanning an 8.7$\times$ parameter range (1.5B--13B) and three architecture families under key conditions; single-seed entries are marked with $^\dag$.
Regex B5 (99.33\%) exploits the \texttt{[No exception data in trace]} format marker, providing a non-learned baseline; its collapse to 28.49\% under marker removal (\S\ref{sec:nomarker}) shows the SFT advantage is not format-driven.

\begin{table}[t]
\centering
\caption{Cross-model verdict accuracy (\%, $N{=}1{,}190$) across four models (1.5B--13B) and three architecture families. For \texttt{exception\_only}, effective $N{\approx}607$ due to within-problem duplicates; CIs use $N{=}1{,}190$ (conservative; deduplication delta ${<}$0.1pp, Appendix~\ref{sec:dedup_stats}). Multi-seed entries report mean$\pm$std over 2--3 seeds; $^\dag$ = single seed (seed 42). Bold: best per model.}
\label{tab:cross_model}
\small
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lcccc}
\toprule
\textbf{Condition} & \textbf{Qwen-7B} & \textbf{Qwen-1.5B} & \textbf{CL-13B} & \textbf{DS-6.7B} \\
\midrule
exception\_only & \textbf{99.83}{\scriptsize$\pm$0.00} & \textbf{99.83}{\scriptsize$\pm$0.00} & \textbf{99.89}{\scriptsize$\pm$0.10} & \textbf{99.39}{\scriptsize$\pm$0.10} \\
ae\_only & 99.64{\scriptsize$\pm$0.49} & 98.83{\scriptsize$\pm$0.36} & 99.08{\scriptsize$\pm$0.00} & 98.53{\scriptsize$\pm$0.30} \\
VOTA & 99.05{\scriptsize$\pm$0.38} & 99.54{\scriptsize$\pm$0.06} & 98.74{\scriptsize$\pm$0.24} & 99.25$^\ddag$ \\
loop\_only & 86.05{\scriptsize$\pm$0.52} & 79.54{\scriptsize$\pm$1.42} & 77.40{\scriptsize$\pm$1.54} & 80.31{\scriptsize$\pm$1.65} \\
full\_trace & 81.44{\scriptsize$\pm$1.11} & 77.06$^\dag$ & 79.9$^\S$ & 79.16$^\dag$ \\
no\_trace & 76.42{\scriptsize$\pm$2.31} & 72.35{\scriptsize$\pm$4.48} & 76.47$^\dag$ & 73.36$^\dag$ \\
\midrule
Regex B5 (marker) & \multicolumn{4}{c}{99.33} \\
Majority baseline & \multicolumn{4}{c}{71.51} \\
\bottomrule
\end{tabular}%
}
\vspace{2pt}
\par\raggedright\footnotesize
$^\ddag$DeepSeek VOTA seed 42 (84.45\%) is a tokenizer-driven truncation failure (Appendix~\ref{sec:tokenizer_analysis}), reported as 2-seed mean.
$^\S$CodeLlama \texttt{full\_trace} not available; head-2048 proxy reported.
Per-seed breakdowns for all conditions in Appendix~\ref{sec:full_results}.
\end{table}

\paragraph{Exception dominance across families.}
Under \texttt{exception\_only}, all four models achieve ${\geq}$99.33\% across all available seeds (Table~\ref{tab:cross_model}), spanning only 0.50pp across architectures (the tightest of any condition).
CodeLlama-13B seed 123 achieves 100\%, indicating the 2 persistent errors (\texttt{GeneratorExit}; Appendix~\ref{sec:irreducible}) are convergence artifacts; 99.83\% is a floor, not a ceiling.

\paragraph{Within-range scale patterns.}
Within the tested 1.5B--13B range (8.7$\times$), Tier~1 signals show no scale sensitivity: both \texttt{exception\_only} and \texttt{ae\_only} span ${\leq}$1.2pp.
\texttt{loop\_only} spans 8.65pp, with CodeLlama-13B below Qwen-1.5B, suggesting architecture matters more than parameter count for lower-density signals.
In contrast, \texttt{no\_trace} scales with capacity (Figure~\ref{fig:cross_scale}) and shows the highest seed variance ($\sigma{=}$4.48pp).

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{fig3_cross_model_gap}
\vspace{-6pt}
\caption{Verdict accuracy vs.\ model scale. \texttt{exception\_only} maintains ${\geq}$99.33\% regardless of scale, while \texttt{no\_trace} shows monotonic sensitivity (+4.12pp). \texttt{nomarker} (markers removed) shows no scale degradation.}
\label{fig:cross_scale}
\vspace{-8pt}

